import { redirect } from "next/navigation";
import { requireAuth } from "@/lib/auth-guard";
import { LoginRequired } from "@/shared/ui/LoginRequired";
import { createClient } from "@/lib/supabase/server";
import { getUserProfileOnboarding } from "@/lib/supabase/helpers";
import { getTranslations } from "next-intl/server";
import { AlertCircle } from "lucide-react";
import Link from "next/link";

export const runtime = 'nodejs';

export const dynamic = "force-dynamic";

// Fallback UI for når datahenting feiler (brukervennlig med oversatt tekst)
function OnboardingErrorFallback({
  locale,
  title,
  message,
  retry,
  backToLogin,
}: {
  locale: string;
  title: string;
  message: string;
  retry: string;
  backToLogin: string;
}) {
  return (
    <div className="min-h-screen bg-[#0A0B0D] flex items-center justify-center p-6">
      <div className="max-w-md w-full bg-red-900/20 border border-red-500/20 rounded-xl p-6 text-center">
        <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
        <h2 className="text-xl font-semibold text-red-500 mb-2">{title}</h2>
        <p className="text-red-400/80 mb-4">{message}</p>
        <div className="flex gap-3 justify-center">
          <Link
            href={`/${locale}/onboarding`}
            className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg transition-colors"
          >
            {retry}
          </Link>
          <Link
            href={`/${locale}/login`}
            className="px-4 py-2 bg-[#2A2D35] hover:bg-[#3A3D45] text-[#F9FAFB] rounded-lg transition-colors"
          >
            {backToLogin}
          </Link>
        </div>
      </div>
    </div>
  );
}

export default async function OnboardingPage({
  params,
}: {
  params: Promise<{ locale: string }>;
}) {
  let locale = "no";
  try {
    const { locale: l } = await params;
    locale = l;
    const { user } = await requireAuth(locale);
    if (!user) {
      return <LoginRequired next={`/${locale}/onboarding`} />;
    }

    const supabase = createClient();
    const { data: profile } = await getUserProfileOnboarding(supabase, user.id);

    // Hvis fullført → dashboard
    if (profile?.onboarding_completed) {
      redirect(`/${locale}/dashboard`);
    }

    // 3-stegs flyt basert på onboarding_step
    const step = profile?.onboarding_step || 0;
    const steps = [
      "/onboarding/step1-welcome",
      "/onboarding/step2-level",
      "/onboarding/step4-first-trade",
    ];
    const targetStep = Math.min(step, steps.length - 1);

    redirect(`/${locale}${steps[targetStep]}`);
  } catch (error) {
    // Next.js redirect() throws NEXT_REDIRECT – må rethrow så framework håndterer den
    if (
      error &&
      typeof error === "object" &&
      "digest" in error &&
      String((error as { digest?: string }).digest).startsWith("NEXT_REDIRECT")
    ) {
      throw error;
    }
    console.error("Onboarding page error:", error);
    const t = await getTranslations("onboarding");
    return (
      <OnboardingErrorFallback
        locale={locale}
        title={t("error.title")}
        message={t("error.message")}
        retry={t("error.retry")}
        backToLogin={t("error.backToLogin")}
      />
    );
  }
}
